import { test, expect } from '@playwright/test';

test.describe('Search Results Update with Debounce', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should update search results as user types with debounce', async ({ page }) => {
    // Setup API interception for search endpoint
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Get search input by role
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await expect(searchInput).toBeVisible();

    // Get search results container by role
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Get search results list by role
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    // Get search result item by role
    const resultItem = page.getByRole('listitem', { name: /result/i });
    await expect(resultItem).toBeVisible();

    // Verify initial state
    await expect(resultsList).toHaveCount(0);

    // Type a query
    await searchInput.fill('playwright');

    // Wait for debounce
    await page.waitForTimeout(300);

    // Verify results are displayed
    await expect(resultsList).toHaveCount(1);

    // Verify result item contains expected text
    await expect(resultItem).toContainText('playwright');

    // Type more characters to trigger multiple updates
    await searchInput.fill('playwright test');

    // Wait for debounce
    await page.waitForTimeout(300);

    // Verify results are updated
    await expect(resultsList).toHaveCount(2);

    // Verify result item contains expected text
    await expect(resultItem).toContainText('playwright test');

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();
  });

  test('should handle empty search query and display no results', async ({ page }) => {
    // Setup API interception for search endpoint
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Get search input by role
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await expect(searchInput).toBeVisible();

    // Get search results container by role
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Get search results list by role
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    // Get search result item by role
    const resultItem = page.getByRole('listitem', { name: /result/i });
    await expect(resultItem).toBeVisible();

    // Verify initial state
    await expect(resultsList).toHaveCount(0);

    // Clear search input
    await searchInput.fill('');

    // Wait for debounce
    await page.waitForTimeout(300);

    // Verify no results are displayed
    await expect(resultsList).toHaveCount(0);

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();
  });
});
